messages.content:
Tool response:
Tool: check_equipment_availability
Description: Check Equipment Availability
Parameters:
    {
      "type": "object",
      "properties": {
        "equipment_name": {
          "type": "string",
          "description": "Name of the equipment to check",
          "title": "Equipment Name"
        },
        "start_time": {
          "type": "string",
          "description": "Start datetime in ISO format (e.g., 2025-03-20T09:00:00)",
          "title": "Start Time"
        },
        "end_time": {
          "type": "string",
          "description": "End datetime in ISO format (e.g., 2025-03-20T12:00:00)",
          "title": "End Time"
        }
      },
      "required": [
        "equipment_name",
        "start_time",
        "end_time"
      ]
    }
